	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Farm
	 */
		public Farm createFarm( CreateFarmCommand command ) {

		Farm entity = new Farm();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setFarmId( command.getFarmId() );
            entity.setName( command.getName() );
            entity.setFarmCode( command.getFarmCode() );
            entity.setTotalArea( command.getTotalArea() );
            entity.setAddress( command.getAddress() );
            entity.setFarmType( command.getFarmType() );
            entity.setAreaUnit( command.getAreaUnit() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Farm {0} ", entity.toString() );

		return entity;
	}

