	/**
	 * Method to retrieve the Farm via FarmFetchOneSummary.
	 * @param 	summary FarmFetchOneSummary
	 * @return 	FarmFetchOneResponse
	 */
	public Farm getFarm( FarmFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "FarmFetchOneSummary arg cannot be null" );

		Farm entity = null;
		UUID id = summary.getId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Farm using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


